let strings = vec!["LGR", "22", "7"];

let (numbers, errors): (Vec<_>, Vec<_>) = strings

  .into_iter()

  .map(|s| s.parse::<i32>())

  .partition(Result::is_ok);

let numbers: Vec<_> = numbers

  .into_iter()

  .map(Result::unwrap)

  .collect();

let errors: Vec<_> = errors

  .into_iter()

  .map(Result::unwrap_err)

  .collect();

